import subprocess
import json
import os

def run_aws_cli_command(command):
    try:
        # Using shell=True for simpler command execution, assuming AWS CLI is in PATH
        # and region/credentials are configured via environment variables or default profile
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=True,
            shell=True
        )
        # AWS CLI outputs JSON to stdout
        return json.loads(result.stdout)
    except subprocess.CalledProcessError as e:
        # print(f"Error executing command: {command}")
        # print(f"Stderr: {e.stderr}")
        # Return None or empty list/dict based on expected output structure
        return None
    except json.JSONDecodeError:
        # print(f"Could not decode JSON from: {command}")
        # print(f"Stdout: {result.stdout}")
        return None

def infer_language_from_runtime(runtime):
    if not runtime:
        return "Unknown"
    runtime = runtime.lower()
    if runtime.startswith("python"):
        return "Python"
    elif runtime.startswith("nodejs"):
        return "Node.js"
    elif runtime.startswith("java"):
        return "Java"
    elif runtime.startswith("dotnet"):
        return "C#"
    elif runtime.startswith("go"):
        return "Go"
    elif runtime.startswith("ruby"):
        return "Ruby"
    elif runtime.startswith("provided"): # Custom runtime implies it could be anything, or a container
        return "Custom/Container"
    return "Unknown"

def infer_language_from_image_name(image_name):
    image_name = image_name.lower()
    if "python" in image_name:
        return "Python"
    elif "node" in image_name or "nodejs" in image_name:
        return "Node.js"
    elif "java" in image_name:
        return "Java"
    elif "php" in image_name:
        return "PHP"
    elif "ruby" in image_name:
        return "Ruby"
    elif "go" in image_name:
        return "Go"
    elif "dotnet" in image_name or "aspnet" in image_name:
        return "C#"
    # Check for common base images for containers that might imply language
    # This is a heuristic and might not be perfectly accurate
    if "alpine" in image_name or "ubuntu" in image_name or "centos" in image_name:
        return "Linux (Generic)" # Could be anything on top
    return "Unknown"

def main():
    discovery_results = {
        "ec2_instances": [],
        "ecs_services": [],
        "lambda_functions": [],
        "rds_instances": [],
        "sqs_queues": [],
        "s3_buckets": []
    }

    # Discover EC2 Instances
    # print("Discovering EC2 Instances...")
    ec2_data = run_aws_cli_command(["aws ec2 describe-instances --query 'Reservations[].Instances[]'"])
    if ec2_data:
        for instance in ec2_data:
            discovery_results["ec2_instances"].append({
                "id": instance.get("InstanceId"),
                "type": instance.get("InstanceType"),
                "state": instance.get("State", {}).get("Name"),
                "tags": {tag["Key"]: tag["Value"] for tag in instance.get("Tags", [])} if instance.get("Tags") else {},
                "platform": instance.get("PlatformDetails")
            })

    # Discover ECS Services
    # print("Discovering ECS Services...")
    list_clusters_output = run_aws_cli_command(["aws ecs list-clusters"])
    if list_clusters_output and "clusterArns" in list_clusters_output:
        for cluster_arn in list_clusters_output["clusterArns"]:
            cluster_name = cluster_arn.split('/')[-1]
            list_services_output = run_aws_cli_command([f"aws ecs list-services --cluster {cluster_name}"])
            if list_services_output and "serviceArns" in list_services_output and list_services_output["serviceArns"]:
                # AWS CLI describe-services can take multiple ARNs, but subprocess.run needs careful handling of list args with shell=True
                # For simplicity and robustness with shell=True, describe services one by one or batch carefully.
                # Let's batch them in chunks to avoid command line limits, though a single call might work for many.
                service_arns_str = ' '.join(list_services_output["serviceArns"])
                describe_services_output = run_aws_cli_command([
                    f"aws ecs describe-services --cluster {cluster_name} --services {service_arns_str}"
                ])
                if describe_services_output and "services" in describe_services_output:
                    for service in describe_services_output["services"]:
                        service_info = {
                            "cluster_name": cluster_name,
                            "service_name": service.get("serviceName"),
                            "status": service.get("status"),
                            "desired_count": service.get("desiredCount"),
                            "running_count": service.get("runningCount"),
                            "task_definition": service.get("taskDefinition"),
                            "container_images": [],
                            "inferred_languages": []
                        }
                        task_definition_arn = service.get("taskDefinition")
                        if task_definition_arn:
                            describe_task_def_output = run_aws_cli_command([
                                f"aws ecs describe-task-definition --task-definition {task_definition_arn}"
                            ])
                            if describe_task_def_output and "taskDefinition" in describe_task_def_output:
                                for container_def in describe_task_def_output["taskDefinition"].get("containerDefinitions", []):
                                    image = container_def.get("image")
                                    if image:
                                        service_info["container_images"].append(image)
                                        lang = infer_language_from_image_name(image)
                                        if lang != "Unknown" and lang not in service_info["inferred_languages"]:
                                            service_info["inferred_languages"].append(lang)
                        discovery_results["ecs_services"].append(service_info)

    # Discover Lambda Functions
    # print("Discovering Lambda Functions...")
    lambda_data = run_aws_cli_command(["aws lambda list-functions"])
    if lambda_data and "Functions" in lambda_data:
        for func in lambda_data["Functions"]:
            runtime = func.get("Runtime")
            discovery_results["lambda_functions"].append({
                "name": func.get("FunctionName"),
                "runtime": runtime,
                "handler": func.get("Handler"),
                "memory_mb": func.get("Memory"),
                "timeout_sec": func.get("Timeout"),
                "inferred_language": infer_language_from_runtime(runtime)
            })

    # Discover RDS Instances
    # print("Discovering RDS Instances...")
    rds_data = run_aws_cli_command(["aws rds describe-db-instances"])
    if rds_data and "DBInstances" in rds_data:
        for db_instance in rds_data["DBInstances"]:
            discovery_results["rds_instances"].append({
                "id": db_instance.get("DBInstanceIdentifier"),
                "engine": db_instance.get("Engine"),
                "engine_version": db_instance.get("EngineVersion"),
                "status": db_instance.get("DBInstanceStatus"),
                "instance_class": db_instance.get("DBInstanceClass"),
                "endpoint_address": db_instance.get("Endpoint", {}).get("Address")
            })

    # Discover SQS Queues
    # print("Discovering SQS Queues...")
    sqs_data = run_aws_cli_command(["aws sqs list-queues"])
    if sqs_data and "QueueUrls" in sqs_data:
        for queue_url in sqs_data["QueueUrls"]:
            discovery_results["sqs_queues"].append({
                "url": queue_url,
                "name": queue_url.split('/')[-1]
            })

    # Discover S3 Buckets
    # print("Discovering S3 Buckets...")
    s3_data = run_aws_cli_command(["aws s3api list-buckets"])
    if s3_data and "Buckets" in s3_data:
        for bucket in s3_data["Buckets"]:
            discovery_results["s3_buckets"].append({
                "name": bucket.get("Name"),
                "creation_date": bucket.get("CreationDate")
            })

    # Save to JSON file
    output_filename = "aws_microservice_assessment.json"
    with open(output_filename, "w") as f:
        json.dump(discovery_results, f, indent=4)
    # print(f"Discovery complete. Results saved to {output_filename}")

if __name__ == "__main__":
    main()
EOF"
  }
}
